-- Reference data, generated by `npm run seed` from data/. Don't edit by hand: change data/,
-- run the seed, and it writes a new migration when anything differs. Safe to apply twice.
on conflict (id) do update set name = excluded.name, starts_at = excluded.starts_at, ends_at = excluded.ends_at;

on conflict (id) do update set species_id = excluded.species_id, dex_number = excluded.dex_number, types = excluded.types, sprite_key = excluded.sprite_key;

on conflict (form_id, locale) do update set name = excluded.name;

on conflict (id) do update set category = excluded.category, mega_target = excluded.mega_target, mega_base_form = excluded.mega_base_form, sprite_key = excluded.sprite_key;

on conflict (item_id, locale) do update set name = excluded.name;

on conflict (id) do update set form_id = excluded.form_id, position = excluded.position;

on conflict (variant_id, locale) do update set name = excluded.name;

-- M-C: legal forms, items and Mega Evolutions. Megas go first and come back last,
-- since they reference the item list.
delete from public.regulation_megas where regulation_id = 'M-C';
